.theia-Tree .ReactVirtualized__List:focus .theia-TreeNode.theia-mod-focus {
  outline-width: 1px;
  outline-style: solid;
  outline-offset: -1px;
  outline-color: var(--theia-focusBorder);
}

.theia-TreeNodeInfo {
